#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PLAYERS 1000
#define MAX_FILE (7 + MAX_PLAYERS * (1 + 20 + 4 + 1))

struct player {
    char name[21];
    uint32_t score;
    uint8_t level;
};

static void put_u16(unsigned char *out, uint16_t v)
{
    out[0] = (unsigned char)(v & 0xFF);
    out[1] = (unsigned char)(v >> 8);
}

static void put_u32(unsigned char *out, uint32_t v)
{
    for (int i = 0; i < 4; i++) out[i] = (unsigned char)(v >> (8 * i));
}

static uint16_t get_u16(const unsigned char *in)
{
    return (uint16_t)(in[0] | (in[1] << 8));
}

static uint32_t get_u32(const unsigned char *in)
{
    return (uint32_t)in[0] | (uint32_t)in[1] << 8 | (uint32_t)in[2] << 16 | (uint32_t)in[3] << 24;
}

static int parse_player(const char *line, struct player *p)
{
    char name[64];
    unsigned long long score = 0;
    unsigned int level = 0;
    char extra = 0;
    if (sscanf(line, "%63s %llu %u %c", name, &score, &level, &extra) != 3) return 0;
    if (strchr(line, '-') != NULL) return 0;
    size_t length = strlen(name);
    if (length < 1 || length > 20 || score > UINT32_MAX || level > 255) return 0;
    memcpy(p->name, name, length + 1);
    p->score = (uint32_t)score;
    p->level = (uint8_t)level;
    return 1;
}

static size_t encode(const struct player *players, size_t count, unsigned char *out)
{
    size_t at = 0;
    memcpy(out, "XSAV", 4);
    at += 4;
    out[at++] = 1;
    put_u16(out + at, (uint16_t)count);
    at += 2;
    for (size_t i = 0; i < count; i++) {
        size_t length = strlen(players[i].name);
        out[at++] = (unsigned char)length;
        memcpy(out + at, players[i].name, length);
        at += length;
        put_u32(out + at, players[i].score);
        at += 4;
        out[at++] = players[i].level;
    }
    return at;
}

static void hex_dump(const unsigned char *bytes, size_t size)
{
    for (size_t offset = 0; offset < size; offset += 16) {
        printf("%08zx  ", offset);
        for (size_t i = 0; i < 16; i++) {
            if (offset + i < size) printf("%02x ", bytes[offset + i]);
            else printf("   ");
        }
        printf(" |");
        for (size_t i = 0; i < 16 && offset + i < size; i++) {
            unsigned char c = bytes[offset + i];
            putchar(c >= 32 && c <= 126 ? c : '.');
        }
        printf("|\n");
    }
}

static void decode(const unsigned char *bytes, size_t size)
{
    if (size < 7 || memcmp(bytes, "XSAV", 4) != 0 || bytes[4] != 1) {
        printf("Not a save file\n");
        return;
    }
    uint16_t count = get_u16(bytes + 5);
    size_t at = 7;
    for (uint16_t i = 0; i < count; i++) {
        if (at + 1 > size) break;
        size_t length = bytes[at++];
        if (length < 1 || length > 20 || at + length + 5 > size) {
            printf("Not a save file\n");
            return;
        }
        char name[21];
        memcpy(name, bytes + at, length);
        name[length] = '\0';
        at += length;
        uint32_t score = get_u32(bytes + at);
        at += 4;
        uint8_t level = bytes[at++];
        printf("%s: score %" PRIu32 ", level %u\n", name, score, (unsigned)level);
    }
}

int main(void)
{
    static struct player players[MAX_PLAYERS];
    size_t count = 0;
    char line[256];
    while (fgets(line, sizeof line, stdin) != NULL) {
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') continue;
        if (count < MAX_PLAYERS && parse_player(line, &players[count])) count++;
        else printf("Skipped: %s\n", line);
    }

    static unsigned char out[MAX_FILE];
    size_t size = encode(players, count, out);
    FILE *f = fopen("save.bin", "wb");
    if (f == NULL) {
        perror("save.bin");
        return 1;
    }
    fwrite(out, 1, size, f);
    fclose(f);

    f = fopen("save.bin", "rb");
    if (f == NULL) {
        perror("save.bin");
        return 1;
    }
    static unsigned char back[MAX_FILE + 1];
    size_t got = fread(back, 1, sizeof back, f);
    fclose(f);

    printf("save.bin: %zu bytes\n", got);
    hex_dump(back, got);
    decode(back, got);
    return 0;
}
